/* Safelight local ZIP runtime. Implements the JSZip subset used by the app; no network dependency. */
(function(global){
  'use strict';
  const te=new TextEncoder();
  const crcTable=new Uint32Array(256);
  for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1);crcTable[n]=c>>>0}
  function crc32(bytes){let c=0xffffffff;for(let i=0;i<bytes.length;i++)c=crcTable[(c^bytes[i])&255]^(c>>>8);return(c^0xffffffff)>>>0}
  function u16(v){return new Uint8Array([v&255,(v>>>8)&255])}
  function u32(v){return new Uint8Array([v&255,(v>>>8)&255,(v>>>16)&255,(v>>>24)&255])}
  function join(parts){let len=0;for(const p of parts)len+=p.length;const out=new Uint8Array(len);let o=0;for(const p of parts){out.set(p,o);o+=p.length}return out}
  function dosDateTime(date){date=date||new Date();const year=Math.max(1980,date.getFullYear());return{time:((date.getHours()&31)<<11)|((date.getMinutes()&63)<<5)|((date.getSeconds()/2)&31),date:(((year-1980)&127)<<9)|(((date.getMonth()+1)&15)<<5)|(date.getDate()&31)}}
  async function bytesOf(value){
    if(value instanceof Uint8Array)return value;
    if(ArrayBuffer.isView(value))return new Uint8Array(value.buffer,value.byteOffset,value.byteLength);
    if(value instanceof ArrayBuffer)return new Uint8Array(value);
    if(typeof Blob!=='undefined'&&value instanceof Blob)return new Uint8Array(await value.arrayBuffer());
    if(typeof value==='string')return te.encode(value);
    if(value==null)return new Uint8Array();
    return te.encode(String(value));
  }
  class JSZipLite{
    constructor(){this.files=[]}
    file(name,value){this.files.push({name:String(name),value});return this}
    async generateAsync(options){
      options=options||{};
      const locals=[],centrals=[];let offset=0;
      for(const entry of this.files){
        const name=te.encode(entry.name),data=await bytesOf(entry.value),crc=crc32(data),dt=dosDateTime(new Date());
        const local=join([u32(0x04034b50),u16(20),u16(0x0800),u16(0),u16(dt.time),u16(dt.date),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),name,data]);
        locals.push(local);
        const central=join([u32(0x02014b50),u16(20),u16(20),u16(0x0800),u16(0),u16(dt.time),u16(dt.date),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),name]);
        centrals.push(central);offset+=local.length;
      }
      let centralSize=0;for(const c of centrals)centralSize+=c.length;
      const eocd=join([u32(0x06054b50),u16(0),u16(0),u16(this.files.length),u16(this.files.length),u32(centralSize),u32(offset),u16(0)]);
      const out=join([...locals,...centrals,eocd]);
      if(options.type==='uint8array')return out;
      if(options.type==='arraybuffer')return out.buffer.slice(out.byteOffset,out.byteOffset+out.byteLength);
      return new Blob([out],{type:'application/zip'});
    }
  }
  JSZipLite.support={blob:typeof Blob!=='undefined'};
  global.JSZip=JSZipLite;
})(window);
